-- Insert 60+ new challenging questions to diversify the quiz
INSERT INTO public.questions (theme, question, options, correct_answer, explanation, difficulty) VALUES
-- PRINCIPES ET VALEURS - Questions difficiles
('principes_valeurs', 'Quel article de la Constitution de 1958 définit les caractéristiques de la République française ?', '["Article 1er", "Article 2", "Article 3", "Article 5"]', 0, 'L''article 1er de la Constitution définit la France comme "une République indivisible, laïque, démocratique et sociale".', 'difficile'),
('principes_valeurs', 'En quelle année le suffrage universel masculin a-t-il été définitivement établi en France ?', '["1789", "1848", "1871", "1914"]', 1, 'Le suffrage universel masculin a été établi définitivement en 1848 sous la IIe République.', 'difficile'),
('principes_valeurs', 'Qui a composé les paroles de La Marseillaise ?', '["Victor Hugo", "Claude Joseph Rouget de Lisle", "Jean-Jacques Rousseau", "Voltaire"]', 1, 'La Marseillaise a été composée par Claude Joseph Rouget de Lisle à Strasbourg en 1792.', 'moyen'),
('principes_valeurs', 'Quel principe républicain garantit l''égal accès de tous aux services publics ?', '["La laïcité", "L''égalité", "La fraternité", "La continuité"]', 1, 'Le principe d''égalité garantit l''égal accès de tous les citoyens aux services publics.', 'moyen'),
('principes_valeurs', 'Que représente le faisceau de licteur sur les armoiries de la France ?', '["La force par l''union", "La justice", "La liberté", "L''agriculture"]', 0, 'Le faisceau de licteur symbolise la force par l''union : les baguettes liées ensemble sont plus solides qu''isolées.', 'difficile'),
('principes_valeurs', 'Quelle est la signification de "République indivisible" ?', '["Le territoire ne peut être divisé", "Les pouvoirs sont séparés", "Le président est unique", "L''armée est unifiée"]', 0, 'L''indivisibilité signifie que le territoire national ne peut être morcelé et que la souveraineté est une.', 'moyen'),
('principes_valeurs', 'Depuis quand le 14 juillet est-il officiellement la fête nationale ?', '["1789", "1880", "1848", "1870"]', 1, 'Le 14 juillet a été déclaré fête nationale par la loi du 6 juillet 1880.', 'difficile'),
('principes_valeurs', 'Quel principe interdit au président de la République de prendre en compte la religion d''un citoyen ?', '["La démocratie", "La laïcité", "L''égalité", "La fraternité"]', 1, 'La laïcité impose la neutralité de l''État vis-à-vis des religions.', 'facile'),

-- SYSTEME INSTITUTIONNEL - Questions variées
('systeme_institutionnel', 'Quelle institution vérifie la constitutionnalité des lois ?', '["Le Conseil d''État", "La Cour de cassation", "Le Conseil constitutionnel", "Le Parlement"]', 2, 'Le Conseil constitutionnel vérifie la conformité des lois à la Constitution.', 'moyen'),
('systeme_institutionnel', 'Combien de membres composent le Conseil constitutionnel ?', '["7", "9", "11", "15"]', 1, 'Le Conseil constitutionnel compte 9 membres nommés pour 9 ans, plus les anciens présidents de la République.', 'difficile'),
('systeme_institutionnel', 'Qui préside le Conseil des ministres ?', '["Le Premier ministre", "Le Président de la République", "Le Garde des Sceaux", "Le Président de l''Assemblée nationale"]', 1, 'Le Président de la République préside le Conseil des ministres chaque mercredi.', 'moyen'),
('systeme_institutionnel', 'Quelle est la durée du mandat d''un sénateur ?', '["5 ans", "6 ans", "7 ans", "9 ans"]', 1, 'Les sénateurs sont élus pour un mandat de 6 ans.', 'moyen'),
('systeme_institutionnel', 'Qui peut dissoudre l''Assemblée nationale ?', '["Le Premier ministre", "Le Président de la République", "Le Président du Sénat", "Le Conseil constitutionnel"]', 1, 'Le Président de la République peut dissoudre l''Assemblée nationale après consultation du Premier ministre.', 'moyen'),
('systeme_institutionnel', 'Quel article de la Constitution permet au Président d''exercer des pouvoirs exceptionnels ?', '["Article 5", "Article 12", "Article 16", "Article 49"]', 2, 'L''article 16 permet au Président de prendre des mesures exceptionnelles en cas de crise grave.', 'difficile'),
('systeme_institutionnel', 'Comment s''appelle le représentant de l''État dans chaque département ?', '["Le maire", "Le préfet", "Le conseiller général", "Le sous-préfet"]', 1, 'Le préfet représente l''État dans le département et veille à l''application des lois.', 'facile'),
('systeme_institutionnel', 'Quelle institution peut renverser le gouvernement par une motion de censure ?', '["Le Sénat", "L''Assemblée nationale", "Le Conseil constitutionnel", "Le Conseil d''État"]', 1, 'Seule l''Assemblée nationale peut renverser le gouvernement par une motion de censure.', 'moyen'),
('systeme_institutionnel', 'Quel organe est le juge administratif suprême en France ?', '["La Cour de cassation", "Le Conseil d''État", "Le Conseil constitutionnel", "La Cour des comptes"]', 1, 'Le Conseil d''État est la plus haute juridiction administrative.', 'difficile'),
('systeme_institutionnel', 'En quelle année la Ve République a-t-elle été instaurée ?', '["1946", "1954", "1958", "1962"]', 2, 'La Ve République a été instaurée par la Constitution du 4 octobre 1958.', 'facile'),
('systeme_institutionnel', 'Qui était le premier président de la Ve République ?', '["Vincent Auriol", "René Coty", "Charles de Gaulle", "Georges Pompidou"]', 2, 'Charles de Gaulle fut le premier président de la Ve République, élu en 1958.', 'facile'),

-- DROITS ET DEVOIRS - Questions approfondies
('droits_devoirs', 'Quel âge minimum faut-il avoir pour être élu président de la République ?', '["18 ans", "21 ans", "23 ans", "Aucun âge minimum"]', 0, 'Depuis 2011, il n''y a plus d''âge minimum, seule la majorité (18 ans) est requise.', 'difficile'),
('droits_devoirs', 'Le recensement citoyen est obligatoire à partir de quel âge ?', '["16 ans", "17 ans", "18 ans", "21 ans"]', 0, 'Le recensement citoyen est obligatoire dès 16 ans pour tous les Français.', 'moyen'),
('droits_devoirs', 'Quand peut-on refuser de témoigner en justice ?', '["Jamais", "Si le témoin risque de s''auto-incriminer", "Si on ne connaît pas l''accusé", "Si on est malade"]', 1, 'On peut refuser de témoigner si cela risque de nous incriminer ou d''incriminer un proche.', 'difficile'),
('droits_devoirs', 'Combien de signatures de maires faut-il pour se présenter à la présidence ?', '["100", "300", "500", "1000"]', 2, 'Il faut 500 signatures d''élus, dont des maires, pour se présenter à l''élection présidentielle.', 'difficile'),
('droits_devoirs', 'Quel document est nécessaire pour circuler librement dans l''espace Schengen ?', '["Le passeport uniquement", "La carte d''identité ou le passeport", "Le permis de conduire", "Un visa Schengen"]', 1, 'Une carte d''identité ou un passeport en cours de validité suffit pour circuler dans l''espace Schengen.', 'moyen'),
('droits_devoirs', 'Qu''est-ce que le Défenseur des droits ?', '["Un avocat gratuit", "Une autorité indépendante de protection des droits", "Un juge spécialisé", "Un député"]', 1, 'Le Défenseur des droits est une autorité indépendante chargée de défendre les droits des citoyens.', 'moyen'),
('droits_devoirs', 'À quel âge peut-on être juré d''assises ?', '["18 ans", "21 ans", "23 ans", "25 ans"]', 2, 'Il faut avoir au moins 23 ans pour être juré d''assises.', 'difficile'),
('droits_devoirs', 'Quel article de la DDHC proclame que "Les hommes naissent libres et égaux en droits" ?', '["Article 1er", "Article 2", "Article 3", "Article 4"]', 0, 'L''article 1er de la Déclaration des Droits de l''Homme et du Citoyen de 1789.', 'moyen'),
('droits_devoirs', 'Qu''est-ce que la "non-assistance à personne en danger" ?', '["Un droit", "Un délit pénal", "Une faute civile", "Une infraction mineure"]', 1, 'La non-assistance à personne en danger est un délit puni par le Code pénal.', 'moyen'),
('droits_devoirs', 'Pendant combien de temps doit-on conserver ses bulletins de salaire ?', '["1 an", "5 ans", "10 ans", "Toute sa vie"]', 3, 'Il est recommandé de conserver ses bulletins de salaire toute sa vie pour la retraite.', 'moyen'),

-- HISTOIRE ET GÉOGRAPHIE - Questions culturelles
('histoire_geographie', 'Quel roi a fait construire le château de Versailles ?', '["Louis XIII", "Louis XIV", "Louis XV", "Louis XVI"]', 1, 'Louis XIV, le Roi-Soleil, a fait construire le château de Versailles à partir de 1661.', 'facile'),
('histoire_geographie', 'Quelle est la plus haute montagne de France ?', '["Le Mont Blanc", "Le Pic du Midi", "Le Puy de Dôme", "La Barre des Écrins"]', 0, 'Le Mont Blanc culmine à 4 807 mètres, c''est le plus haut sommet des Alpes et de France.', 'facile'),
('histoire_geographie', 'En quelle année Napoléon Bonaparte est-il devenu empereur ?', '["1799", "1802", "1804", "1806"]', 2, 'Napoléon Bonaparte a été sacré empereur le 2 décembre 1804.', 'moyen'),
('histoire_geographie', 'Quel traité a créé la Communauté économique européenne (CEE) ?', '["Traité de Paris", "Traité de Rome", "Traité de Maastricht", "Traité de Lisbonne"]', 1, 'Le Traité de Rome de 1957 a créé la CEE, ancêtre de l''Union européenne.', 'moyen'),
('histoire_geographie', 'Combien de départements compte la France métropolitaine ?', '["95", "96", "100", "101"]', 1, 'La France métropolitaine compte 96 départements (y compris la Corse qui en compte 2).', 'moyen'),
('histoire_geographie', 'Quelle est la devise de l''Union européenne ?', '["Paix et Prospérité", "Unie dans la diversité", "Force et Honneur", "Liberté et Justice"]', 1, 'La devise de l''Union européenne est "Unie dans la diversité" (In varietate concordia).', 'moyen'),
('histoire_geographie', 'Quel écrivain français a écrit "Les Misérables" ?', '["Émile Zola", "Victor Hugo", "Gustave Flaubert", "Honoré de Balzac"]', 1, 'Victor Hugo a écrit "Les Misérables", publié en 1862.', 'facile'),
('histoire_geographie', 'En quelle année l''esclavage a-t-il été définitivement aboli en France ?', '["1794", "1802", "1848", "1870"]', 2, 'L''esclavage a été définitivement aboli le 27 avril 1848 par Victor Schœlcher.', 'moyen'),
('histoire_geographie', 'Quelle bataille marque la fin du Premier Empire napoléonien ?', '["Austerlitz", "Iéna", "Waterloo", "Borodino"]', 2, 'La bataille de Waterloo en 1815 marque la fin définitive de l''Empire napoléonien.', 'moyen'),
('histoire_geographie', 'Quel président français a instauré le quinquennat ?', '["François Mitterrand", "Jacques Chirac", "Nicolas Sarkozy", "Valéry Giscard d''Estaing"]', 1, 'Le quinquennat a été adopté par référendum en 2000 sous la présidence de Jacques Chirac.', 'moyen'),
('histoire_geographie', 'Quelle est la population approximative de la France ?', '["55 millions", "62 millions", "68 millions", "75 millions"]', 2, 'La France compte environ 68 millions d''habitants en 2024.', 'facile'),
('histoire_geographie', 'Quel monument parisien a été construit pour l''Exposition universelle de 1889 ?', '["L''Arc de Triomphe", "Le Sacré-Cœur", "La Tour Eiffel", "Le Panthéon"]', 2, 'La Tour Eiffel a été construite par Gustave Eiffel pour l''Exposition universelle de 1889.', 'facile'),

-- VIVRE EN SOCIÉTÉ - Questions pratiques
('vivre_societe', 'À partir de quel âge l''instruction est-elle obligatoire en France ?', '["3 ans", "5 ans", "6 ans", "7 ans"]', 0, 'L''instruction est obligatoire à partir de 3 ans depuis 2019.', 'moyen'),
('vivre_societe', 'Jusqu''à quel âge l''instruction est-elle obligatoire ?', '["14 ans", "16 ans", "18 ans", "21 ans"]', 1, 'L''instruction est obligatoire jusqu''à 16 ans en France.', 'facile'),
('vivre_societe', 'Quel est le salaire minimum en France (nom) ?', '["Revenu Minimum", "SMIC", "RSA", "Salaire de Base"]', 1, 'Le SMIC (Salaire Minimum Interprofessionnel de Croissance) est le salaire minimum légal.', 'facile'),
('vivre_societe', 'Quelle est la durée légale hebdomadaire du travail en France ?', '["32 heures", "35 heures", "38 heures", "40 heures"]', 1, 'La durée légale du travail est de 35 heures par semaine depuis les lois Aubry de 1998-2000.', 'facile'),
('vivre_societe', 'Quel est l''âge légal de départ à la retraite (minimum) ?', '["60 ans", "62 ans", "64 ans", "65 ans"]', 2, 'L''âge légal de départ à la retraite est de 64 ans depuis la réforme de 2023.', 'moyen'),
('vivre_societe', 'Qu''est-ce que la carte Vitale ?', '["Une carte d''identité", "Une carte bancaire", "La carte d''assurance maladie", "Une carte de transport"]', 2, 'La carte Vitale est la carte d''assurance maladie qui permet le remboursement des soins.', 'facile'),
('vivre_societe', 'Combien de jours de congés payés minimum un salarié a-t-il par an ?', '["20 jours", "25 jours", "30 jours", "35 jours"]', 1, 'Tout salarié a droit à 25 jours ouvrés de congés payés minimum (5 semaines).', 'moyen'),
('vivre_societe', 'Qu''est-ce que le PACS ?', '["Un permis de conduire", "Un contrat d''union civile", "Une aide sociale", "Un diplôme"]', 1, 'Le PACS (Pacte Civil de Solidarité) est un contrat d''union civile entre deux personnes.', 'facile'),
('vivre_societe', 'Depuis quand le mariage pour tous est-il légal en France ?', '["2008", "2011", "2013", "2015"]', 2, 'Le mariage pour tous a été légalisé par la loi du 17 mai 2013.', 'moyen'),
('vivre_societe', 'Quel numéro appeler en cas d''urgence médicale ?', '["15", "17", "18", "112"]', 0, 'Le 15 est le numéro du SAMU pour les urgences médicales. Le 112 est le numéro européen.', 'facile'),
('vivre_societe', 'Quel numéro appeler pour la police ?', '["15", "17", "18", "114"]', 1, 'Le 17 est le numéro de Police Secours.', 'facile'),
('vivre_societe', 'Combien de temps dure le congé maternité minimum en France ?', '["8 semaines", "12 semaines", "16 semaines", "20 semaines"]', 2, 'Le congé maternité est de 16 semaines minimum pour le premier et deuxième enfant.', 'moyen'),
('vivre_societe', 'Qu''est-ce que le RSA ?', '["Un diplôme", "Le Revenu de Solidarité Active", "Une taxe", "Un permis"]', 1, 'Le RSA (Revenu de Solidarité Active) est une aide financière pour les personnes sans ressources.', 'facile'),
('vivre_societe', 'Quel document prouve qu''on a le droit de travailler en France ?', '["La carte Vitale", "Un titre de séjour autorisant le travail ou la nationalité française", "Le permis de conduire", "La carte de transport"]', 1, 'Pour travailler en France, il faut être français, européen, ou avoir un titre de séjour autorisant le travail.', 'moyen'),
('vivre_societe', 'À quel âge peut-on passer le permis de conduire en France ?', '["16 ans", "17 ans", "18 ans", "21 ans"]', 2, 'L''âge minimum pour passer le permis B est 18 ans (17 ans avec la conduite accompagnée).', 'facile'),
('vivre_societe', 'Qu''est-ce que Pôle emploi (France Travail) ?', '["Une entreprise privée", "Le service public de l''emploi", "Une école", "Un ministère"]', 1, 'France Travail (ex Pôle emploi) est le service public de l''emploi en France.', 'facile');